                id = SchemaId.V201909;
            } else if (id.contains("/draft/2020-12/")) {
                id = SchemaId.V202012;
            } else if (id.contains("/draft-04/")) {
                id = SchemaId.V4;
            } else if (id.contains("/draft-06/")) {
                id = SchemaId.V6;
            }
        }
    }
    return id;
}

